package owner.buriedoiltank.data;

import java.util.List;

/** Public, self-reported research targets. Never a validator, risk score or case record. */
public final class TankDocumentCheck {
    private TankDocumentCheck() {}
    public static final String PATH = "/tank-document-check/";
    public record Document(String id, String label, String meaning, String match) {}
    public record Situation(String id, String label, String answer, List<String> targets, String next) {}
    public record Region(String id, String label, String distinction, String sourceLabel, String sourceUrl, List<String> routes) {}
    public static final List<Document> DOCUMENTS = List.of(
        new Document("permit", "Tank-work permit", "Records permission for the described work, not necessarily its completion.", "Match issuer, property, work type and permit number; request the actual final disposition."),
        new Document("completion", "Final inspection / completion record", "Records the issuer's stated work outcome within its scope.", "Match the permit, tank location, work date and removal versus closure-in-place wording."),
        new Document("work", "Contractor's tank-work report", "Describes the reported tank work; an invoice alone may not contain the supporting report.", "Check tank identity, method, photographs, disposal references and named attachments."),
        new Document("lab", "Sampling report and lab attachments", "Documents the samples described in that report, not a guarantee about all soil or future conditions.", "Ask a qualified environmental professional to review sampling locations, dates, methods and any missing laboratory pages."),
        new Document("agency", "Environmental case papers, if applicable", "Address a particular spill or cleanup case; they are not issued for every tank removal.", "Match the case reference and the actual final correspondence, its conditions and referenced reports."),
        new Document("sweep", "Physical tank-search report", "Describes the survey performed and its limitations; it is not a historic removal certificate.", "Read inspected areas, method, access restrictions and unresolved findings with the survey provider."),
        new Document("conversion", "Oil-to-gas / heat-pump conversion papers", "Document heating-system work, not necessarily what happened to the former tank.", "Look for a separate tank-work reference rather than assuming conversion includes removal."),
        new Document("reply", "Agency no-records reply", "Reports the outcome of that agency's search within its stated scope.", "Keep the agency, record categories, date range and any referral; it is not a tank-free finding.")
    );
    private static Situation s(String id, String label, String answer, String next, String... targets) {
        return new Situation(id, label, answer, List.of(targets), next);
    }
    public static final List<Situation> SITUATIONS = List.of(
        s("home-sale", "Buying or selling: assemble the tank file", "Start with what happened to the tank, then match the work record and any separate environmental case. This checklist does not decide whether to buy, sell or close.", "Give your transaction professional a list of documents held, gaps and pending agency requests. Keep the deadline separate from the time a custodian may need.", "work", "completion", "agency"),
        s("missing-removal-records", "Tank removed, but no certificate or report", "A missing removal certificate is a document gap, not proof that removal did or did not occur. Identify the local work record and any separate environmental file.", "Ask the local record holder for the final inspection/completion attachment tied to the reported work, not simply another permit index search.", "work", "completion"),
        s("seller-says-tank-removed", "Seller says the tank was removed", "Preserve the exact claim: removed, emptied and filled in place are different actions. Compare the claim with property-matched work and completion records.", "Ask for the underlying report and completion record, including the tank location and work method. Unresolved physical presence belongs with a qualified survey provider.", "work", "completion"),
        s("conflicting-tank-documents", "The documents disagree", "First check whether the papers describe the same tank and the same stage of work. An issued permit, contractor invoice and environmental letter answer different questions.", "Build a dated comparison and ask the issuer about the exact mismatch. Do not choose the most reassuring document or treat an old report as a present-condition inspection.", "permit", "completion", "work"),
        s("agency-record-request", "An agency search or request is incomplete", "A receipt, referral, no-records reply and delivered document are different outcomes. The scope of the agency search matters as much as its status.", "Name the missing existing document, known reference and dates. Keep the request pending until the actual response arrives; a draft here sends nothing.", "permit", "completion", "reply"),
        s("records-or-tank-sweep", "I do not know whether a tank is still there", "Records investigate documented history; a physical survey investigates the area and conditions within its scope. Neither automatically replaces the other.", "Use the record trail for historic work and discuss unresolved physical presence with a qualified tank-search provider. Obtain owner permission before any site investigation.", "work", "sweep"),
        s("oil-tank-filled-with-sand", "Tank filled with sand or foam and left underground", "Filled in place is not removed. The fill material alone does not establish the complete work, sampling or environmental history.", "Request the closure-in-place work report, available inspection and sampling attachments. Ask a qualified professional about gaps rather than inferring no leak from the fill material.", "work", "completion", "lab"),
        s("oil-to-gas-tank-records", "Converted to gas or a heat pump; tank history unknown", "A new heating system does not establish what happened to the old oil tank. Trace tank work separately from conversion work.", "Ask for the separate tank permit/report and identify which property areas remain uninvestigated. Conversion papers and an empty database search do not resolve physical presence.", "conversion", "work", "completion"),
        s("oil-tank-open-permit", "Permit issued, but no final inspection or closeout", "A permit issue date is not a completion date. A blank online final status may need an attachment search or clarification from the issuer.", "Ask the issuing office for the permit's final disposition and any inspection/completion record. Keep an environmental case separate; this tool cannot close a permit.", "permit", "completion"),
        s("nfa-vs-removal-certificate", "NFA letter versus removal certificate", "An environmental closure letter and a local tank-work record have different scopes. In NJ, an NFA is not needed for every clean UHOT closure that passed municipal inspection.", "Match each paper to its issuer and case/permit reference. If a cleanup case exists, obtain its actual correspondence; do not invent a missing NFA requirement for every removal.", "completion", "agency"),
        s("oil-tank-soil-test-records", "Report says soil tested, but sampling pages are missing", "A statement that testing occurred is not the sampling and laboratory file. Records can locate the evidence; interpreting adequacy needs a qualified environmental professional.", "Request the sample-location plan, sampling report, laboratory results and referenced attachments by report/case number. Do not infer a clean property from a missing page or summary sentence.", "work", "lab", "agency")
    );
    public static Situation situation(String id) {
        return SITUATIONS.stream().filter(s -> s.id().equals(id)).findFirst().orElse(SITUATIONS.get(0));
    }
    public static final List<Region> REGIONS = List.of(
        new Region("other", "Other location / not sure", "Confirm the legal jurisdiction and the office holding tank-work records. A state facility registry may exclude home heating-oil tanks. No tailored rule for your location is implied here.", "EPA: heating-oil tank scope", "https://www.epa.gov/ust/frequent-questions-about-underground-storage-tanks", List.of()),
        new Region("new-jersey", "New Jersey", "Keep municipal permits/completion records separate from NJDEP remediation papers. NJDEP says an NFA is not needed for a UHOT closure with no evidence of discharge that passed municipal inspection. This checklist does not establish those conditions for your property.", "NJDEP UHOT FAQs, questions 15, 17 and 30", "https://dep.nj.gov/srp/unregulated/unregulated-faqs/", List.of("njdep-nfa-letter", "njdep-tank-documents", "maplewood-nj")),
        new Region("new-york", "New York", "NYSDEC says most home heating-oil tanks below 1,100 gallons are outside state PBS regulation, with delegated-county differences. Check local work records separately from spill records. Nassau's small-tank verification route is not statewide.", "NYSDEC homeowner guide", "https://dec.ny.gov/environmental-protection/hazardous-substance-bulk-storage/underground-heating-oil-tanks-homeowner-guide", List.of("nassau-ny", "suffolk-ny", "westchester-ny", "nysdec-spill-documents")),
        new Region("oregon", "Oregon", "DEQ distinguishes emptying from decommissioning. Clean-decommissioning certificates and leaking-HOT projects use different record searches. Ask about older missing files; do not treat an emptying receipt as a decommissioning report.", "Oregon DEQ buying/selling guidance", "https://www.oregon.gov/deq/tanks/pages/hot-buying-or-selling.aspx", List.of("oregon-clean-decommissioning", "oregon-leaking-tank-records", "portland-or")),
        new Region("washington", "Washington", "Tank-work records follow the actual city or county custodian. Seattle's residential dataset distinguishes permit issuance from reported decommissioning details and has historical limits; it is not a statewide lookup.", "Seattle residential UST dataset", "https://data.seattle.gov/Built-Environment/Underground-Storage-Tank-UST-Records-Residential/xvj2-ai6y", List.of("seattle-residential-tank-records", "king-county-wa", "bellevue-wa", "tacoma-wa"))
    );
    public static List<ResearchCatalog.Entry> routes(Region region) {
        return region.routes().stream().map(ResearchCatalog::find).toList();
    }
}
